'use strict';

// MODULES //

var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var format = require( '@stdlib/string/format' );
var aliases = require( '@stdlib/namespace/aliases' );


// VARIABLES //

var RE_IDENTIFIER = /\b(?:var|let|const|(?:async\s+)?function\*?) +([a-zA-Z_$][a-zA-Z0-9_$]*)/g;
var GLOBALS = buildLookup();


// FUNCTIONS //

/**
* Builds a lookup table of global identifiers from the stdlib namespace aliases.
*
* @private
* @returns {Object} lookup table
*/
function buildLookup() {
	var lookup;
	var list;
	var idx;
	var i;

	list = aliases();
	lookup = {};
	for ( i = 0; i < list.length; i++ ) {
		idx = list[ i ].indexOf( '.' );
		if ( idx === -1 ) {
			lookup[ list[ i ] ] = true;
		} else {
			lookup[ list[ i ].substring( 0, idx ) ] = true;
		}
	}
	return lookup;
}


// MAIN //

/**
* Rule for enforcing that identifiers declared within an examples section do not collide with global identifiers in the REPL namespace.
*
* @param {Context} context - lint context
* @returns {Object} validators
*/
function main( context ) {
	/**
	* Checks an examples section for identifiers that collide with global identifiers.
	*
	* @private
	* @param {Object} section - examples section
	*/
	function noGlobalCollision( section ) {
		var examples;
		var match;
		var i;

		examples = section.examples;
		for ( i = 0; i < examples.length; i++ ) {
			RE_IDENTIFIER.lastIndex = 0;
			match = RE_IDENTIFIER.exec( examples[ i ].code );
			while ( match ) {
				if ( hasOwnProp( GLOBALS, match[ 1 ] ) ) {
					context.report( format( '%s collides with a global identifier', match[ 1 ] ), section );
				}
				match = RE_IDENTIFIER.exec( examples[ i ].code );
			}
		}
	}

	return {
		'examples': noGlobalCollision
	};
}


// EXPORTS //

module.exports = main;
